mapper.sql:
WHERE status <> 'DELETED'
AND status = #{status}
AND engine_type = #{engineType}

    AND (data_source_code LIKE CONCAT('%', #{keyword}, '%') OR data_source_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
UPDATE t_data_source
SET status = #{status}, version = version + 1, updated_by = #{updatedBy}, update_time = #{updateTime}
WHERE data_source_id = #{row.dataSourceId} AND version = #{row.version} AND status = #{row.status}

UPDATE t_data_source
SET last_check_result = #{result}, last_check_message = #{message}, last_check_time = #{checkTime}
WHERE data_source_id = #{dataSourceId} AND status <> 'DELETED'
